let t,lang,icon,a,choose;
const labels=()=>choose(['Calls & leads','Scheduling & dispatch','HomPassport™'],['Appels et prospects','Agenda et répartition','HomPassport™']);
function callsPanel(){return `<div class="workspace-heading"><div><span class="tiny-label">${choose('EVERY CONVERSATION, CONNECTED','CHAQUE CONVERSATION, CONNECTÉE')}</span><h3>${choose('From a call to a confirmed job.','D’un appel à un rendez-vous confirmé.')}</h3></div><span class="soft-badge">${icon('phone')}Maya · 24/7</span></div><div class="call-overview"><div class="call-summary"><div class="call-summary-top"><div class="caller-icon">${icon('users')}</div><div><h4>${choose('HVAC repair','Réparation CVAC')}</h4><span>${choose('Homeowner · Incoming call','Propriétaire · Appel entrant')}</span></div><span class="pill success">${choose('Booked','Confirmé')}</span></div><div class="transcript"><span class="transcript-label">${choose('CONVERSATION PREVIEW','EXEMPLE DE CONVERSATION')}</span><div class="speech maya-speech"><span>MAYA</span><p>${choose('Hi, thanks for calling. How can I help?','Bonjour, merci de votre appel. Comment puis-je vous aider ?')}</p></div><div class="speech"><span>${choose('HOMEOWNER','PROPRIÉTAIRE')}</span><p>${choose('Our air conditioning hasn’t been cooling since this morning.','Notre climatiseur ne refroidit plus depuis ce matin.')}</p></div><div class="speech maya-speech"><span>MAYA</span><p>${choose('I can book a technician for Tuesday at 2:30 PM. Does that work for you?','Je peux vous envoyer un technicien mardi à 14 h 30. Cela vous convient ?')}</p></div></div><div class="call-bottom">${icon('file')}${choose('Call details, ready for your team','Les détails de l’appel, prêts pour votre équipe')}</div></div><div class="workflow"><p class="tiny-label">${choose('MAYA TAKES CARE OF THE REST','MAYA S’OCCUPE DE LA SUITE')}</p>${t.hero.mockup.steps.slice(1).map((s,i)=>`<div class="workflow-step"><div class="step-dot">${icon(['phone','users','calendar','check'][i])}</div><div><strong>${s.label}</strong><span>${s.detail}</span></div></div>`).join('')}<div class="sent-confirmation">${icon('check')}${choose('Homeowner & technician notified','Le client et le technicien sont informés')}</div></div></div>`;}
function schedulePanel(){return `<div class="workspace-heading"><div><span class="tiny-label">${choose('THE RIGHT CREW. THE RIGHT TIME.','LA BONNE ÉQUIPE. AU BON MOMENT.')}</span><h3>${choose('A schedule that keeps moving.','Un agenda qui fait avancer vos équipes.')}</h3></div><span class="soft-badge">${icon('calendar')}${choose('Tuesday','Mardi')}</span></div><div class="schedule-demo"><div class="day-column"><div class="day-head"><strong>${choose('Your schedule','Votre agenda')}</strong><span>${choose('Example day','Journée type')}</span></div>${[['09:00',choose('Equipment maintenance','Entretien d’équipement'),choose('Service visit','Visite de service')],['11:00',choose('Customer follow-up','Suivi client'),choose('Appointment confirmed','Rendez-vous confirmé')],['14:30',choose('HVAC repair','Réparation CVAC'),choose('Booked by Maya · Marco','Réservé par Maya · Marco')]].map((x,i)=>`<div class="calendar-row"><time>${x[0]}</time><div class="calendar-event ${i===2?'booked-event':''}"><strong>${x[1]}</strong><span>${x[2]}</span></div></div>`).join('')}</div><div class="dispatch-note"><div class="status-icon">${icon('users')}</div><h4>${choose('From first ring<br>to crew on site.','Du premier appel<br>à l’équipe sur place.')}</h4><p>${choose('Maya checks availability, respects your service areas and job durations, then sends the schedule to your technician.','Maya vérifie les disponibilités, respecte vos zones de service et la durée des interventions, puis envoie l’horaire au technicien.')}</p><span class="pill success">${icon('check')}${choose('SMS & email confirmations','Confirmations SMS et courriel')}</span></div></div>`;}
function passportPanel(){return `<div class="workspace-heading"><div><span class="tiny-label">${choose('EVERY HOME HAS A STORY','CHAQUE MAISON A SON HISTOIRE')}</span><h3>${choose('One home. Every detail.','Une maison. Tous les détails.')}</h3></div><span class="soft-badge">HomPassport™</span></div><div class="passport-demo"><div class="property-summary"><span class="property-icon">${icon('home')}</span><h4>${choose('Your customer’s home','La maison de votre client')}</h4><p>${choose('One secure, living service record.','Un dossier vivant, centralisé et sécurisé.')}</p><div class="property-stat">${icon('shield')}${choose('Secure homeowner access','Accès sécurisé pour le propriétaire')}</div></div><div class="property-details">${[[choose('Equipment','Équipements'),choose('Make, model & serial number','Marque, modèle et numéro de série'),'bolt'],[choose('Service history','Historique des interventions'),choose('Visits, repairs, parts & photos','Visites, réparations, pièces et photos'),'clock'],[choose('Warranty & documents','Garanties et documents'),choose('Warranty notes & owner’s manuals','Garanties et manuels d’utilisation'),'file'],[choose('Maintenance','Entretien'),choose('Reminders & recurring service plans','Rappels et plans d’entretien récurrents'),'calendar']].map(x=>`<div>${icon(x[2])}<span><strong>${x[0]}</strong><small>${x[1]}</small></span>${icon('check')}</div>`).join('')}</div></div>`;}
function platform(){return `<section id="platform" class="section platform-section"><div class="container"><div class="section-heading horizontal"><div><p class="eyebrow"><span class="red-line"></span>${choose('ONE CONNECTED WORKFLOW','UN PARCOURS CONNECTÉ')}</p><h2>${choose('Every call.<br>A clear next step.','Chaque appel.<br>Une suite évidente.')}</h2></div><p>${t.features.description}</p></div><div class="platform-tabs" role="tablist" aria-label="${choose('Explore the platform','Explorer la plateforme')}">${labels().map((label,i)=>`<button role="tab" id="platform-tab-${i}" aria-controls="product-view-${i}" aria-selected="${i===0}" tabindex="${i===0?0:-1}" data-tab="${i}">${icon(['phone','calendar','home'][i])}${label}</button>`).join('')}</div><div class="product-stage"><div class="workspace"><div class="workspace-chrome"><div class="window-dots"><i></i><i></i><i></i></div><span>HomPilot <span class="slash">/</span>${choose('Your workspace','Votre espace de travail')}</span><span class="example-label">${choose('Illustrative preview','Aperçu illustratif')}</span></div><div class="workspace-body"><aside class="workspace-sidebar"><span class="workspace-brand">HomPilot<span>®</span></span><span class="workspace-caption">${choose('WORKSPACE','ESPACE DE TRAVAIL')}</span>${labels().map((x,i)=>`<button class="workspace-link ${i===0?'selected':''}" data-panel="${i}">${icon(['phone','calendar','home'][i])}<span>${x}</span></button>`).join('')}<div class="workspace-maya"><img src="/brand/maya-avatar.jpg" alt="" width="34" height="34"><div><strong>Maya</strong><small>${choose('Ready for the next call','Prête pour le prochain appel')}</small></div><span class="availability"></span></div></aside><div class="workspace-main">${[callsPanel(),schedulePanel(),passportPanel()].map((panel,i)=>`<div id="product-view-${i}" role="tabpanel" aria-labelledby="platform-tab-${i}" ${i?'hidden':''}>${panel}</div>`).join('')}</div></div></div><div class="stage-caption"><span>${icon('spark')}${choose('Connected by HomPilot. Powered by Maya.','Connecté par HomPilot. Propulsé par Maya.')}</span><a class="text-link" href="#booking">${choose('See it in action','Voir en action')}${icon('arrow')}</a></div></div><div class="feature-rail">${[[choose('24/7 reception','Réception 24/7'),'phone'],[choose('Qualified leads','Prospects qualifiés'),'users'],[choose('Scheduling','Rendez-vous'),'calendar'],[choose('Quotes & billing','Devis et facturation'),'file'],[choose('Customer portal','Portail client'),'home'],[choose('Team dispatch','Répartition d’équipe'),'bolt']].map(x=>`<div>${icon(x[1])}<span>${x[0]}</span></div>`).join('')}</div></div></section>`;}
function mediaCard(type,title){const sources={csr:choose('maya-csr-en-v2','maya-csr-fr'),dispatcher:choose('maya-dispatcher-en-v3','maya-dispatcher-v2'),workforce:choose('maya-9agents-en','maya-9agents-fr')};return `<div class="media-card"><video src="/brand/${sources[type]}.mp4" poster="/brand/${type}-poster.jpg" preload="none" loop muted playsinline aria-label="${title}"></video><button class="media-play" data-inline-play aria-label="${choose('Play video','Lire la vidéo')} — ${title}">${icon('play')}</button><div class="media-caption"><span>${title}</span><button class="icon-button" data-inline-sound aria-label="${choose('Enable sound','Activer le son')}">${icon('mute')}</button></div></div>`;}
function maya(){return `<section id="maya" class="section maya-section"><div class="container two-columns"><div class="maya-media">${mediaCard('csr',choose('Meet your AI receptionist','Votre réceptionniste IA'))}<div class="media-footnote"><span class="red-line"></span>${choose('Real conversations. In English and French.','De vraies conversations. En français et en anglais.')}</div></div><div class="section-copy"><p class="eyebrow"><span class="red-line"></span>${choose('MEET MAYA','VOICI MAYA')}</p><h2>${choose('Your best<br>first impression.<br><span class="muted-heading">Every time.</span>','Un premier contact<br>impeccable.<br><span class="muted-heading">À chaque appel.</span>')}</h2><p>${t.csr.subtitle}</p><div class="benefit-list">${[[choose('Every call answered, day or night','Chaque appel pris en charge, jour et nuit'),'phone'],[choose('Leads qualified. Appointments booked.','Prospects qualifiés. Rendez-vous confirmés.'),'calendar'],[choose('A natural voice, in both languages','Une voix naturelle, dans les deux langues'),'message']].map(x=>`<div>${icon(x[1])}<span>${x[0]}</span></div>`).join('')}</div><button class="text-link" data-talk>${t.hero.ctaPrimary}${icon('arrow')}</button></div></div></section>`;}
function dispatch(){return `<section class="section dispatch-section"><div class="container two-columns"><div class="section-copy"><p class="eyebrow"><span class="red-line"></span>${choose('LESS ADMIN. MORE MOMENTUM.','MOINS D’ADMIN. PLUS D’ACTION.')}</p><h2>${choose('Keep your team<br>in the field.<br><span class="muted-heading">Not on the phone.</span>','Votre équipe<br>sur le terrain.<br><span class="muted-heading">L’esprit tranquille.</span>')}</h2><p>${t.dispatcher.subtitle}</p><a class="text-link" href="#platform" data-open-schedule>${choose('Explore scheduling & dispatch','Découvrir l’agenda et la répartition')}${icon('arrow')}</a><div class="mini-proof"><span><strong>24/7</strong>${choose('Always answering','Toujours à l’écoute')}</span><span><strong>EN / FR</strong>${choose('Naturally bilingual','Naturellement bilingue')}</span><span><strong>10 min</strong>${choose('To get started','Pour démarrer')}</span></div></div><div class="dispatch-media">${mediaCard('dispatcher',t.dispatcher.title)}<div class="dispatch-message">${icon('message')}<span>${choose('The right information. Straight to your technician.','La bonne information. Directement au technicien.')}</span>${icon('check')}</div></div></div></section>`;}
function passport(){const bullets=t.homPassport.bullets||t.homPassport.items||t.homPassport.features||choose(['Equipment inventory (make, model, serial number, install date & warranty)','Complete service history (visits, repairs, parts & photos)','Maintenance reminders & recurring service plans','Warranty documents & owner’s manuals','Secure homeowner portal with lifetime access'],['Inventaire des équipements : marque, modèle, numéro de série et garantie','Historique complet : visites, réparations, pièces et photos','Rappels et plans d’entretien récurrents','Documents de garantie et manuels d’utilisation','Portail propriétaire sécurisé avec accès à vie']);return `<section id="hompassport" class="section passport-section"><div class="container two-columns"><div class="passport-art"><div class="passport-card"><div class="passport-card-head"><span class="passport-monogram">H<span>•</span></span><div>HomPassport<span>™</span><small>${choose('A living record of every home','Le dossier vivant de chaque maison')}</small></div>${icon('shield')}</div><div class="passport-row">${icon('home')}<div><strong>${choose('Every detail, in one place.','Chaque détail, au même endroit.')}</strong><span>${choose('Connected to your customer. Ready for your team.','Connecté au client. Prêt pour votre équipe.')}</span></div></div>${bullets.map((x,i)=>`<div class="passport-item"><span class="passport-item-icon">${icon(['bolt','clock','calendar','file','shield'][i])}</span><p>${x}</p>${icon('check','passport-check')}</div>`).join('')}<div class="passport-powered"><span class="availability"></span>${t.homPassport.badge}</div></div><span class="passport-caption">${choose('YOUR CUSTOMER RELATIONSHIP, BUILT TO LAST.','UNE RELATION CLIENT QUI DURE.')}</span></div><div class="section-copy"><p class="eyebrow"><span class="red-line"></span>HOMPASSPORT™</p><h2>${choose('Know the home.<br>Before you<br>ring the bell.','Connaître la maison.<br>Avant même<br>d’y arriver.')}</h2><p>${t.homPassport.description}</p><p class="secondary-paragraph">${t.homPassport.descriptionLine2||choose('Your office stops searching for information, your technicians arrive prepared, and homeowners always know what comes next.','Votre bureau ne cherche plus l’information, vos techniciens arrivent préparés et vos clients savent toujours quelle est la prochaine étape.')}</p>${a(choose('Discover HomPassport','Découvrir HomPassport'),'#booking','outline')}</div></div></section>`;}
function workforce(){return `<section id="agents" class="section workforce-section"><div class="container"><div class="section-heading center"><p class="eyebrow">${t.workforce.eyebrow}</p><h2>${choose('One Maya.<br>A whole team behind you.','Une Maya.<br>Toute une équipe à vos côtés.')}</h2><p>${t.workforce.subtitle}</p></div><div class="workforce-theater">${mediaCard('workforce',t.workforce.title)}<a class="agent-directory-link" href="/agents">${choose('Meet all 9 agents','Découvrir les 9 agents')}${icon('arrow')}</a></div><div class="agent-functions">${["Receptionist Pro", "Lead Magnet", "Appointment Scheduler", "Customer Success", "Admin Assistant", "Billing Bot", "Team Coordinator", "Quality Assurance", "AI Coordinator"].map((x,i)=>`<a href="/agents/${i+1}"><span>${String(i+1).padStart(2,'0')}</span>${x}${icon('chevron')}</a>`).join('')}</div></div></section>`;}
function solutions(){return `<section id="solutions" class="section solutions-section"><div class="container"><div class="section-heading horizontal"><div><p class="eyebrow"><span class="red-line"></span>${choose('BUILT AROUND YOUR TRADE','PENSÉ POUR VOTRE MÉTIER')}</p><h2>${t.verticals.title}<span class="red-period">.</span></h2></div><p>${choose('You take care of homes.<br>Maya takes care of the next call.','Vous prenez soin des maisons.<br>Maya s’occupe du prochain appel.')}</p></div><div class="solution-grid">${t.verticals.items.map((x,i)=>`<a href="#booking">${icon(['bolt','home','bolt','home','users','home','home','spark','shield','home'][i])}<span>${x}</span>${icon('arrow')}</a>`).join('')}</div></div></section>`;}
function resources(){return `<section id="resources" class="section resources-section"><div class="container"><div class="demo-banner"><div><p class="eyebrow">${choose('SEE IT FOR YOURSELF','VOYEZ PAR VOUS-MÊME')}</p><h2>${choose('Two minutes.<br>A different workday.','Deux minutes.<br>Une autre journée de travail.')}</h2><p>${t.demo.description}</p><button class="button dark" data-video="demo">${icon('play')}${t.hero.ctaSecondary}</button></div><button class="demo-banner-preview" data-video="demo" aria-label="${t.hero.ctaSecondary}"><img src="/brand/overview-poster.jpg" alt="${choose('Maya connects bookings, estimates and dispatch','Maya relie les rendez-vous, les estimations et la répartition')}" width="1280" height="720" loading="lazy"><span class="large-play">${icon('play')}</span><span class="video-duration">${choose('Explore your AI workforce','Découvrir votre équipe IA')}</span></button></div><div class="extra-video"><span>${choose('A closer look at Maya’s connected workflow','Un aperçu du fonctionnement connecté de Maya')}</span><button class="text-link" data-video="overview">${choose('Watch the overview','Voir la présentation')}${icon('play')}</button></div></div></section>`;}
function faq(){return `<section id="faq" class="section faq-section"><div class="container faq-layout"><div><p class="eyebrow"><span class="red-line"></span>${t.faq.eyebrow}</p><h2>${choose('Good questions.<br>Clear answers.','De bonnes questions.<br>Des réponses claires.')}</h2><p>${choose('Wondering how Maya fits into your business? Let’s make it simple.','Vous vous demandez comment Maya s’intègre à votre entreprise ? Parlons-en simplement.')}</p><button class="text-link" data-talk>${choose('Ask Maya directly','Posez la question à Maya')}${icon('arrow')}</button></div><div class="faq-items">${t.faq.items.map(item=>`<details name="faq"><summary>${item.question}<span>${icon('plus')}</span></summary><p>${item.answer}</p></details>`).join('')}</div></div></section>`;}
function booking(){return `<section id="booking" class="booking-section"><div class="container"><div class="booking-box"><div class="booking-copy"><p class="eyebrow"><span class="availability"></span>${choose('YOUR NEXT CHAPTER STARTS HERE','LA SUITE COMMENCE ICI')}</p><h2>${choose('Your business.<br>A step ahead.','Votre entreprise.<br>Un temps d’avance.')}</h2><p>${t.booking.description}</p><div class="booking-actions"><button class="button red" data-book>${t.nav.cta}${icon('arrow')}</button><button class="button ghost" data-talk>${t.hero.ctaPrimary}${icon('phone')}</button></div><div class="booking-reassurance">${t.finalCta.trust.map(x=>`<span>${icon('check')}${x}</span>`).join('')}</div></div><div class="booking-side"><div class="voice-wave"><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i><i></i></div><p>${choose('Fewer missed calls.<br>More possibilities.','Moins d’appels manqués.<br>Plus de possibilités.')}</p><span>Maya · HomPilot</span></div></div></div></section>`;}
function footer(){return `</main><footer class="footer"><div class="container"><div class="footer-main"><div><a href="/" class="logo"><img src="/brand/hompilot-logo.png" alt="HomPilot" width="145" height="39" loading="lazy"></a><p>${t.footer.tagline}</p></div><div class="footer-links"><a href="#platform">${choose('Platform','Plateforme')}</a><a href="#maya">Maya</a><a href="#hompassport">HomPassport™</a><a href="/agents">${choose('AI workforce','Équipe IA')}</a></div><div class="footer-links"><a href="#solutions">Solutions</a><a href="#resources">${choose('Watch the demo','Voir la démo')}</a><a href="#faq">FAQ</a><a href="tel:+14385335800">(438) 533-5800</a></div></div><div class="footer-bottom"><span>${t.footer.copyright}</span><span class="canadian"><img src="/brand/canada-emoji.jpg" alt="" width="22" height="18" loading="lazy">${t.footer.canadian}</span><a href="#main">${choose('Back to top','Retour en haut')}${icon('arrow')}</a></div></div></footer><dialog id="video-dialog" class="video-dialog"><div class="dialog-header"><span id="video-title">HomPilot · Maya</span><button class="icon-button" data-close aria-label="${choose('Close video','Fermer la vidéo')}">${icon('close')}</button></div><video controls playsinline preload="none" aria-labelledby="video-title"></video></dialog><dialog id="talk-dialog" class="talk-dialog"><button class="dialog-x icon-button" data-close aria-label="${choose('Close','Fermer')}">${icon('close')}</button><div class="status-icon">${icon('phone')}</div><h2>${choose('Say hello to Maya.','Dites bonjour à Maya.')}</h2><p>${choose('Try a real conversation. Call or text Maya and see how she handles your next service request.','Essayez une vraie conversation. Appelez Maya ou envoyez-lui un message pour voir comment elle traite une demande de service.')}</p><a class="button red" href="tel:+14385335800">${icon('phone')}${choose('Call','Appeler')} · (438) 533-5800</a><a class="button outline" href="sms:+14385335800?body=${encodeURIComponent(t.hero.smsBody)}">${icon('message')}${choose('Send a text','Envoyer un SMS')}</a><span class="dialog-footnote">${choose('Available in English and French','Disponible en français et en anglais')}</span></dialog><dialog id="booking-dialog" class="booking-dialog"><div class="dialog-header"><span>${t.booking.title}</span><button class="icon-button" data-close aria-label="${choose('Close booking','Fermer la réservation')}">${icon('close')}</button></div><div class="booking-widget-wrapper"><div id="booking-mount"></div></div><p class="widget-fallback">${choose('Need a hand?','Besoin d’aide ?')} <a href="tel:+14385335800">${choose('Call Maya','Appelez Maya')} · (438) 533-5800</a></p></dialog>`;}
export function sections(content,language,iconFn,buttonFn,chooseFn){[t,lang,icon,a,choose]=[content,language,iconFn,buttonFn,chooseFn];return platform()+maya()+dispatch()+passport()+workforce()+solutions()+resources()+faq()+booking()+footer();}
let lastFocus;
function openDialog(id){stopOtherMedia();lastFocus=document.activeElement;const d=document.getElementById(id);d.showModal();document.body.classList.add('modal-open');d.querySelector('[data-close]')?.focus();}
function stopOtherMedia(except){document.querySelectorAll('video').forEach(v=>{if(v!==except){v.muted=true;if(!v.classList.contains('maya-portrait'))v.pause();const sound=v.closest('.media-card')?.querySelector('[data-inline-sound]');if(sound){sound.innerHTML=icon('mute');sound.setAttribute('aria-label',choose('Enable sound','Activer le son'));}}});}
function setPlatform(index,focus=false){document.querySelectorAll('[data-tab]').forEach((b,i)=>{b.setAttribute('aria-selected',i===index);b.tabIndex=i===index?0:-1;if(focus&&i===index)b.focus();document.getElementById('product-view-'+i).hidden=i!==index;});document.querySelectorAll('[data-panel]').forEach(b=>b.classList.toggle('selected',Number(b.dataset.panel)===index));}
export function wireSections(){
if(matchMedia('(prefers-reduced-motion: reduce)').matches){document.querySelector('.maya-portrait').pause();document.querySelector('.portrait-pause').innerHTML=icon('play');document.querySelector('.portrait-pause').setAttribute('aria-label',choose('Play animation','Lire l’animation'));}
document.querySelectorAll('[data-tab]').forEach(b=>{b.addEventListener('click',()=>setPlatform(Number(b.dataset.tab)));b.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();setPlatform(e.key==='Home'?0:e.key==='End'?2:(Number(b.dataset.tab)+(e.key==='ArrowRight'?1:2))%3,true);}});});
document.querySelectorAll('[data-panel]').forEach(b=>b.addEventListener('click',()=>setPlatform(Number(b.dataset.panel))));document.querySelector('[data-open-schedule]').addEventListener('click',()=>setPlatform(1));
document.querySelectorAll('[data-video]').forEach(b=>b.addEventListener('click',()=>{const v=document.querySelector('#video-dialog video');v.src='/brand/'+(b.dataset.video==='overview'?'maya-hero-v2.mp4':choose('maya-demo-en.mp4','maya-demo-fr-v2.mp4'));v.poster='/brand/'+(b.dataset.video==='overview'?'overview-poster.jpg':'maya-demo-poster.jpg');document.getElementById('video-title').textContent=b.dataset.video==='overview'?choose('Maya · Connected workflow','Maya · Un parcours connecté'):choose('Meet your Maya AI workforce','Découvrez votre équipe IA Maya');stopOtherMedia(v);openDialog('video-dialog');v.muted=false;v.play().catch(()=>{});}));
document.querySelectorAll('[data-talk]').forEach(b=>b.addEventListener('click',()=>openDialog('talk-dialog')));
document.querySelectorAll('dialog:not(.mobile-drawer)').forEach(d=>{d.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>d.close()));d.addEventListener('click',e=>{const r=d.getBoundingClientRect();if(e.target===d&&(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom))d.close();});d.addEventListener('close',()=>{d.querySelector('video')?.pause();document.body.classList.remove('modal-open');lastFocus?.focus();});});
document.querySelectorAll('[data-inline-play]').forEach(b=>{const v=b.closest('.media-card').querySelector('video');b.addEventListener('click',()=>{if(v.paused){stopOtherMedia(v);v.muted=false;v.play().catch(()=>{v.controls=true;});}else v.pause();});v.addEventListener('playing',()=>{b.classList.add('is-playing');b.innerHTML=icon('pause');b.setAttribute('aria-label',choose('Pause video','Mettre la vidéo en pause'));const sound=v.closest('.media-card').querySelector('[data-inline-sound]');sound.innerHTML=icon(v.muted?'mute':'sound');sound.setAttribute('aria-label',v.muted?choose('Enable sound','Activer le son'):choose('Mute video','Couper le son'));});v.addEventListener('pause',()=>{b.classList.remove('is-playing');b.innerHTML=icon('play');b.setAttribute('aria-label',choose('Play video','Lire la vidéo'));});});
document.querySelectorAll('[data-inline-sound]').forEach(b=>b.addEventListener('click',()=>{const v=b.closest('.media-card').querySelector('video');if(v.paused){stopOtherMedia(v);v.muted=false;v.play().catch(()=>{});}else v.muted=!v.muted;b.innerHTML=icon(v.muted?'mute':'sound');b.setAttribute('aria-label',v.muted?choose('Enable sound','Activer le son'):choose('Mute video','Couper le son'));}));
document.querySelector('[data-book]').addEventListener('click',()=>{openDialog('booking-dialog');const host=document.getElementById('booking-mount');if(host.dataset.loaded)return;host.dataset.loaded='true';const script=document.createElement('script');script.src='/integrations/embed-book.js?lang='+lang;script.dataset.companyId='291216ca-9069-4d52-83fd-909004f36369';script.dataset.group='demo';script.dataset.mount='booking-mount';script.dataset.lang=lang;script.onload=()=>{const root=host.shadowRoot;if(root){const theme=document.createElement('style');theme.textContent='.step.on,.btn:not(.ghost):not([disabled]),.day.sel,.slot.sel{background:#df302b!important}.btn:not(.ghost):not([disabled]):hover{background:#c8221d!important}.tier-card.sel,.tier.sel{border-color:#df302b!important}';root.appendChild(theme);}};script.onerror=()=>{host.innerHTML=`<p>${choose('The booking calendar is temporarily unavailable. Please call Maya to arrange your demo.','Le calendrier est temporairement indisponible. Appelez Maya pour réserver votre démo.')}</p>`;delete host.dataset.loaded;};document.body.appendChild(script);});
document.querySelectorAll('a[href^="#"]').forEach(link=>link.addEventListener('click',()=>{const target=document.querySelector(link.getAttribute('href'));if(target){target.setAttribute('tabindex','-1');target.focus({preventScroll:true});}}));
}
